auto func (auto value){ 
    bool is_sorted = true;
    for (size_t i = 1; i < value.size(); ++i) {
        if (value[i-1] > value[i]) {
            is_sorted = false;
            break;
        }
    }
    return is_sorted;
}

auto func (auto value){ 
    return is_sorted(value.begin(), value.end());
}

